Statements are dicts with a 'type' key."""
"""Executes parsed statements. Tables live in the Connection: {name: {'columns': [...], 'rows': [[...]]}}."""
from .parser import parse


class Connection:
    def __init__(self):
        self.tables = {}

    def execute(self, sql):
        st = parse(sql)
        handler = getattr(self, 'exec_' + st['type'])
        return handler(st)

    def exec_create(self, st):
        self.tables[st['table']] = {'columns': st['columns'], 'rows': []}
        return []

    def exec_insert(self, st):
        tbl = self.tables[st['table']]
        for row in st['rows']:
            tbl['rows'].append([evaluate(e, {}) for e in row])
        return []

    def exec_select(self, st):
        if st['from'] is None:
            return [tuple(evaluate(e, {}) for e, _ in st['items'])]
        tbl = self.tables[st['from']]
        out = []
        for row in tbl['rows']:
            env = dict(zip(tbl['columns'], row))
            vals = []
            for e, _alias in st['items']:
                if e == ('star',):
                    vals.extend(row)
                else:
                    vals.append(evaluate(e, env))
            out.append(tuple(vals))
        return out


def evaluate(e, env):
    kind = e[0]
    if kind == 'lit':
        return e[1]
    if kind == 'col':
        return env[e[2]]
    raise NotImplementedError(f'expression {kind}')
"""Recursive-descent parser: tokens -> statement dicts (see ast.py)."""
from .lexer import tokenize


class Parser:
    def __init__(self, sql):
        self.toks = tokenize(sql)
        self.i = 0

    # --- token helpers -------------------------------------------------
    def peek(self, k=0):
        return self.toks[self.i + k]

    def next(self):
        t = self.toks[self.i]
        self.i += 1
        return t

    def accept(self, kind, value=None):
        t = self.peek()
        if t[0] == kind and (value is None or t[1] == value):
            self.i += 1
            return t
        return None

    def expect(self, kind, value=None):
        t = self.accept(kind, value)
        if t is None:
            raise SyntaxError(f'expected {value or kind}, got {self.peek()}')
        return t

    def ident(self):
        return self.expect('IDENT')[1]

    # --- statements ----------------------------------------------------
    def statement(self):
        t = self.peek()
        if t == ('KW', 'SELECT'):
            st = self.select()
        elif t == ('KW', 'CREATE'):
            st = self.create()
        elif t == ('KW', 'INSERT'):
            st = self.insert()
        else:
            raise SyntaxError(f'unsupported statement starting with {t}')
        self.accept('OP', ';')
        self.expect('EOF')
        return st

    def create(self):
        self.expect('KW', 'CREATE'); self.expect('KW', 'TABLE')
        name = self.ident()
        self.expect('OP', '(')
        cols = []
        while True:
            col = self.ident()
            # type name(s) are ignored, like SQLite's loose typing
            while self.peek()[0] in ('IDENT', 'KW') and self.peek()[1] not in (',',):
                if self.peek() == ('OP', ',') or self.peek() == ('OP', ')'):
                    break
                self.next()
            cols.append(col)
            if not self.accept('OP', ','):
                break
        self.expect('OP', ')')
        return {'type': 'create', 'table': name, 'columns': cols}

    def insert(self):
        self.expect('KW', 'INSERT'); self.expect('KW', 'INTO')
        name = self.ident()
        self.expect('KW', 'VALUES')
        rows = []
        while True:
            self.expect('OP', '(')
            row = [self.expr()]
            while self.accept('OP', ','):
                row.append(self.expr())
            self.expect('OP', ')')
            rows.append(row)
            if not self.accept('OP', ','):
                break
        return {'type': 'insert', 'table': name, 'rows': rows}

    def select(self):
        self.expect('KW', 'SELECT')
        items = [self.select_item()]
        while self.accept('OP', ','):
            items.append(self.select_item())
        table = None
        if self.accept('KW', 'FROM'):
            table = self.ident()
        return {'type': 'select', 'items': items, 'from': table}

    def select_item(self):
        if self.accept('OP', '*'):
            return (('star',), None)
        e = self.expr()
        alias = None
        if self.accept('KW', 'AS'):
            alias = self.ident()
        return (e, alias)

    # --- expressions ---------------------------------------------------
    def expr(self):
        return self.primary()

    def primary(self):
        t = self.next()
        if t[0] in ('NUM', 'STR'):
            return ('lit', t[1])
        if t == ('KW', 'NULL'):
            return ('lit', None)
        if t == ('OP', '-') and self.peek()[0] == 'NUM':
            return ('lit', -self.next()[1])
        if t[0] == 'IDENT':
            if self.accept('OP', '.'):
                return ('col', t[1], self.ident())
            return ('col', None, t[1])
        if t == ('OP', '('):
            e = self.expr()
            self.expect('OP', ')')
            return e
        raise SyntaxError(f'unexpected token {t}')


def parse(sql):
    return Parser(sql).statement()
"""Turns SQL text into tokens: (kind, value). kinds: KW, IDENT, NUM, STR, OP, EOF."""
import re

KEYWORDS = {
    'SELECT', 'FROM', 'WHERE', 'CREATE', 'TABLE', 'INSERT', 'INTO', 'VALUES', 'AS', 'NULL',
}

TOKEN_RE = re.compile(r"""
    (?P<ws>\s+)
  | (?P<num>\d+\.\d*|\.\d+|\d+)
  | (?P<str>'(?:[^']|'')*')
  | (?P<ident>[A-Za-z_][A-Za-z_0-9]*)
  | (?P<op><=|>=|<>|!=|\|\||[-+*/%(),.;=<>])
""", re.VERBOSE)


def tokenize(sql):
    out, pos = [], 0
    while pos < len(sql):
        m = TOKEN_RE.match(sql, pos)
        if not m:
            raise SyntaxError(f'bad character at {pos}: {sql[pos:pos+10]!r}')
        pos = m.end()
        kind = m.lastgroup
        text = m.group(kind)
        if kind == 'ws':
            continue
        if kind == 'num':
            out.append(('NUM', float(text) if '.' in text else int(text)))
        elif kind == 'str':
            out.append(('STR', text[1:-1].replace("''", "'")))
        elif kind == 'ident':
            up = text.upper()
            out.append(('KW', up) if up in KEYWORDS else ('IDENT', text))
        else:
            out.append(('OP', text))
    out.append(('EOF', None))
    return out
"""Run minisql against a directory of JSON tests.

usage:
  python3 run_tests.py tests/visible                    # whole suite, summary by category
  python3 run_tests.py tests/visible --category where   # one category
  python3 run_tests.py tests/visible --sample 0.3       # random 30% sample (seeded by time unless --seed)
  python3 run_tests.py tests/visible --list-failing     # print failing test ids
  python3 run_tests.py tests/visible --show where_004   # show one test: setup, query, expected, got
  python3 run_tests.py tests/visible --json out.json    # machine-readable results
  python3 run_tests.py tests/visible --summary          # compact: only the failing categories

A test passes when minisql returns the same rows as SQLite did. Numbers compare by value
(3 == 3.0, rounded to 6 places); NULL is None; row order matters only if the query has ORDER BY.
"""
import argparse, glob, json, os, random, signal, sys, time

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))


def norm(v):
    if isinstance(v, (bytes, bytearray)):
        return ('s', bytes(v).hex())
    if isinstance(v, bool):
        v = int(v)
    if isinstance(v, (int, float)):
        return ('n', round(float(v), 6))
    if v is None:
        return ('0',)
    return ('s', str(v))


def norm_rows(rows, ordered):
    out = [tuple(norm(v) for v in r) for r in rows]
    return out if ordered else sorted(out)


class Timeout(Exception):
    pass


def _alarm(signum, frame):
    raise Timeout()


def run_one(t):
    import minisql
    signal.signal(signal.SIGALRM, _alarm)
    signal.alarm(3)
    try:
        con = minisql.connect()
        for s in t['setup']:
            con.execute(s)
        got = [list(r) for r in con.execute(t['query'])]
        ok = norm_rows(got, t['ordered']) == norm_rows(t['expected'], t['ordered'])
        return ok, got, None
    except Timeout:
        return False, None, 'timeout'
    except BaseException as e:  # engine bugs must not stop the run
        return False, None, f'{type(e).__name__}: {e}'
    finally:
        signal.alarm(0)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('suite')
    ap.add_argument('--category')
    ap.add_argument('--sample', type=float)
    ap.add_argument('--seed', type=int)
    ap.add_argument('--list-failing', action='store_true')
    ap.add_argument('--show')
    ap.add_argument('--json')
    ap.add_argument('--summary', action='store_true', help='one line per failing category')
    a = ap.parse_args()
    files = sorted(glob.glob(os.path.join(a.suite, '*.json')))
    tests = [json.load(open(f)) for f in files]
    if a.show:
        t = next(t for t in tests if t['id'] == a.show)
        ok, got, err = run_one(t)
        print('\n'.join(t['setup'])); print('QUERY:', t['query'])
        print('EXPECTED:', t['expected']); print('GOT:', got if err is None else err); print('PASS' if ok else 'FAIL')
        return
    if a.category:
        tests = [t for t in tests if t['category'] == a.category]
    if a.sample:
        rng = random.Random(a.seed if a.seed is not None else time.time_ns())
        tests = [t for t in tests if rng.random() < a.sample]
    res = {}
    for t in tests:
        ok, got, err = run_one(t)
        res[t['id']] = ok
    bycat = {}
    for t in tests:
        c = bycat.setdefault(t['category'], [0, 0]); c[1] += 1; c[0] += res[t['id']]
    if a.json:
        json.dump(res, open(a.json, 'w'))
    if a.list_failing:
        print('\n'.join(k for k, v in res.items() if not v))
        return
    if a.summary:
        done = sum(1 for p, n in bycat.values() if p == n)
        print(f'categories fully passing: {done}/{len(bycat)}')
        print('failing categories: ' + ', '.join(f'{c} {p}/{n}' for c, (p, n) in sorted(bycat.items()) if p < n))
    else:
        for c in sorted(bycat):
            p, n = bycat[c]
            print(f'{c:22s} {p:3d}/{n:<3d}')
    print(f'TOTAL          {sum(res.values())}/{len(res)}')


