"""AST node types. Expressions are hashable tuples (lists inside are tuples too):
  ('lit', value)  ('col', table_or_None, name)  ('star',)  ('qstar', table)  ('bool', word, 0|1)
  ('bin', op, l, r)   op: OR AND = != < <= > >= IS 'IS NOT' & | << >> + - * / % || -> ->>
  ('unary', op, e)    op: - + ~ NOT
  ('call', NAME, args) or ('call', NAME, args, opts)  opts: sorted (key, value) pairs among
        distinct, order (terms), filter (expr), over (whatever parser.parse_over returns)
  ('case', base_or_None, ((when, then), ...), else_or_None)   ('cast', e, TYPE NAME)
  ('collate', e, NAME)  ('between', e, lo, hi, negated)  ('istrue', e, want_true, negated)
  ('in', e, ('list', exprs) | ('select', stmt) | ('table', name), negated)
  ('like', LIKE|GLOB|REGEXP|MATCH, e, pattern, escape_or_None, negated)
