"""GROUP BY support (query lane). The engine replaces each aggregate call in a grouped query's
expressions with ('lit', value) computed over the group, then evaluates normally.

BUILTIN: UPPER_NAME -> function(list_of_arg_tuples) -> SQL value. Each arg tuple holds the
evaluated arguments for one row of the group (COUNT(*) gets empty tuples). A richer library in
aggregates.py may export AGGREGATES with the same signature; its entries override these.
"""


def _num(v):
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return v
    if isinstance(v, bool):
        return int(v)
