def agg_group_concat(rows):
    parts = [(r[0], r[1] if len(r) > 1 else ',') for r in rows if r[0] is not None]
    if not parts:
        return None
    out = _text(parts[0][0])
    for v, sep in parts[1:]:
        out += ('' if sep is None else _text(sep)) + _text(v)
    return out


