def _type_name(p):
    words = []
    while p.peek()[0] in ('IDENT', 'KW') and p.peek() != ('OP', ')'):
        words.append(p.next()[1])
    if p.accept('OP', '('):
        depth = 1
        while depth:
            t = p.next()
            if t == ('OP', '('):
                depth += 1
            elif t == ('OP', ')'):
                depth -= 1
            elif t[0] == 'EOF':
                raise SyntaxError('unterminated type')
    p.expect('OP', ')')
    return ' '.join(words).upper()


